<?php
declare(strict_types=1);
namespace App\Cms;
use App\Entity\Cms\CmsMenuItem; use App\Repository\Cms\CmsMenuRepository; use Sylius\Component\Channel\Context\ChannelContextInterface; use Sylius\Component\Channel\Model\ChannelInterface; use Sylius\Component\Locale\Context\LocaleContextInterface; use Symfony\Component\Routing\Generator\UrlGeneratorInterface;
final readonly class CmsMenuResolver { public function __construct(private CmsMenuRepository $menus,private ChannelContextInterface $channels,private LocaleContextInterface $locales,private CmsPagePublicationChecker $publication,private UrlGeneratorInterface $router){} /** @return list<array{label:string,url:string,newTab:bool,children:array}> */ public function resolve(string $code):array{$channel=$this->channels->getChannel();$locale=$this->locales->getLocaleCode();$menu=$this->menus->findResolved($code,$channel,$locale);if(!$menu)return[];$nodes=[];$children=[];foreach($menu->getItems() as $i){if(!$i->isEnabled()||$i->getChannel()!==$channel||$i->getLocale()!==$locale)continue;$url=$this->url($i,$channel,$locale);if(!$url)continue;$node=['label'=>$i->getLabel(),'url'=>$url,'newTab'=>$i->isOpenInNewTab(),'children'=>[]];if($i->getParent())$children[$i->getParent()->getId()][]=$node;else$nodes[$i->getId()]=$node;}foreach($children as $id=>$items)if(isset($nodes[$id]))$nodes[$id]['children']=$items;return array_values($nodes);} private function url(CmsMenuItem $i,ChannelInterface $channel,string $locale):?string{return match($i->getTargetType()){CmsMenuItem::PAGE=>$i->getPage()&&$this->publication->isVisible($i->getPage(),$channel,$locale)?'/'.$i->getPage()->getTranslation($locale)?->getSlug():null,CmsMenuItem::ROUTE=>$this->router->generate((string)$i->getRouteName(),$i->getRouteParameters()),CmsMenuItem::URL=>$i->getExternalUrl(),default=>null};} }
